//
// Dev-server search-index cache fix, installed as a Vite plugin by the
// generated config.
//
// VitePress imports its local search index from `/@localSearchIndexroot?v=<n>`,
// and Vite treats any `?v=` query parameter as a pre-bundled dependency version
// stamp, serving it with `Cache-Control: max-age=31536000,immutable`. Because
// that URL carries no project identifier and `<n>` starts from the same counter
// on every dev server, two LuauDocs sites served on the same localhost port
// would share a one-year browser cache entry. Renaming the query parameter to
// `rev=` avoids Vite's immutable cache header (falling back to `no-cache`) while
// still busting the browser module registry on rebuilds. Production builds are
// unaffected because the built search index chunk is content-hashed.
import type { Plugin } from "vite";

export function searchIndexCachePlugin(): Plugin {
	return {
		name: "luaudocs:search-index-cache",
		apply: "serve",
		transform(code, id) {
			// Transform the root search-index entry module that imports the per-locale payloads.
			if (id !== "@localSearchIndex" && id !== "/@localSearchIndex") {
				return undefined;
			}
			return code.replace(/(@localSearchIndex\w*\?)v=/g, "$1rev=");
		},
	};
}
